import {clock,leds} from './fsm-engine.js';
export function mount(root,{signal}){let state='IDLE',history=[],cycle=0;
  root.innerHTML='<p class="notice">Illustrative simulation: generic Moore-machine palletizer-style sequence, not Ethan’s VHDL. Outputs depend only on state. Safe off returns to IDLE on the next clock; this is not a safety controller.</p><div class="prototype-controls"><label>Start<input type="checkbox" data-switch="start"></label><label>Box present<input type="checkbox" data-switch="box"></label><label>Safe / enable<input type="checkbox" data-switch="safe" checked></label><button data-clock>Clock ↑</button><button data-reset>Reset</button></div><h3 data-state></h3><div class="leds"></div><p>IDLE → Start → FEED → Box → PRESS → one clock → EJECT → one clock → IDLE</p><div data-timing></div><p class="source">Each column is one sampled rising edge. Last 24 cycles retained; changing a switch alone does not advance state.</p>';
  function draw(){root.dataset.state=state;root.dataset.cycles=cycle;root.querySelector('[data-state]').textContent=`${state} · clock ${cycle}`;root.querySelector('.leds').innerHTML=Object.entries(leds(state)).map(([key,on])=>`<span class="led ${on?'on':''}">${key.toUpperCase()} ${on?'●':'○'}</span>`).join('');const tracks=['start','box','safe','feed','press','eject'];root.querySelector('[data-timing]').innerHTML=`<svg viewBox="0 0 760 300" aria-label="Synchronized input and Moore output timing diagram">${tracks.map((key,row)=>{const y=35+row*42;let path='';history.forEach((h,i)=>{const x=105+i*25,v=y-(h[key]?18:0);path+=i?`V${v}H${x+25}`:`M${x},${v}H${x+25}`;});return`<text x="5" y="${y}">${key}</text><path d="${path}" fill="none" stroke="${row<3?'#c2cbbd':'#e3b677'}" stroke-width="2"/>`;}).join('')}</svg>`;}
  root.addEventListener('click',e=>{if(e.target.matches('[data-reset]')){state='IDLE';cycle=0;history=[];}if(e.target.matches('[data-clock]')){const inputs=Object.fromEntries([...root.querySelectorAll('[data-switch]')].map(i=>[i.dataset.switch,i.checked]));state=clock(state,inputs);history.push({...inputs,...leds(state)});history=history.slice(-24);cycle++;}draw();},{signal});draw();return()=>root.replaceChildren();
}
